globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-21 12:02:58 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"Claudeを使い「リーマン予想」を証明か　Anthropic数学者が発表　Lean検証も通過、数学界が精査へ","url":"https://japan.cnet.com/article/35255245/","source":"Hatena","published_at":"2026-11-21 08:02","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeを活用した「リーマン予想」の証明、Lean検証を通過し精査へ","summary":"Anthropicの数学者Levent Alpöge氏が、生成AI「Claude」を用いて数学の難問「リーマン予想」の証明を見つけたと発表しました。この証明コードは、コンピューターによる形式検証システム「Lean」を通過しており、MITの研究者らによっても確認されています。\n\nリーマン予想は167年間未解決のミレニアム懸賞問題の一つであり、今回の発表が正式に認められれば数学界における歴史的な快挙となります。現在は世界中の数学者による内容の精査が進められており、AIが数学的難問の解決に寄与できるかという点でも大きな注目を集めています。","importance":10},{"title":"ZOZOTOWNの退会者含む1,518万人分の情報が漏えい　WEAR by ZOZOでも1,393万人分に（ビジネス＋IT） - Yahoo!ニュース","url":"https://news.yahoo.co.jp/articles/1739163b2e1fd496107c05cb8b455d37d52be5d9","source":"Hatena","published_at":"2026-11-21 00:59","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ZOZOTOWNとWEARで計2,900万人超の顧客情報が流出","summary":"ZOZOは、外部サービス「KARTE」への不正アクセスにより、ZOZOTOWNおよびWEAR by ZOZOの会員情報が流出したと発表しました。流出対象は計2,900万人以上に及び、会員IDや年齢、性別などが含まれます。\n\nパスワードやクレジットカード情報は含まれておらず、現時点で二次被害は確認されていません。しかし、委託先経由での大規模な情報漏洩は、企業におけるサプライチェーンセキュリティの脆弱性を改めて浮き彫りにしました。ZOZOは今後、外部サービスで管理する情報の棚卸しを強化する方針です。","importance":9},{"title":"「httpS://」だと暗号化されず平文で送信……「PHP」に約20年潜んでいた脆弱性が解決／問題はいたってシンプル、なんともはや……【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2158241.html","source":"Hatena","published_at":"2026-11-20 18:26","genre":"web","genre_label":"Web開発・言語","headline":"PHPに20年潜んでいた脆弱性、大文字のHTTPSで暗号化がスキップ","summary":"PHPにおいて、URLスキームの大文字・小文字を区別する処理の不備により、HTTPS等の通信が暗号化されずに平文で送信される脆弱性が発見されました。例えば「HTTPS://」と記述するとTLSがスキップされ、パスワードや認証トークンが漏洩するリスクがあります。\n\nこの問題は20年以上前から存在しており、最新のセキュリティアップデートで修正されました。開発者は直ちにPHPをアップデートするか、URLスキームを小文字に正規化するなどの回避策を講じる必要があります。","importance":9},{"title":"dbt v1 でメトリクスを一元管理する未来 〜Apache Ossie と Lightdash で試す〜","url":"https://zenn.dev/kyami/articles/dbt-snowflake-apache-ossie","source":"Zenn","published_at":"2026-11-19 22:48","genre":"other","genre_label":"総合・その他IT","headline":"dbt v1とApache Ossieによるメトリクス一元管理の検証","summary":"dbtで定義したメトリクスからSnowflakeのSemantic Viewを生成する「Apache Ossie」の検証記事。これまでdbtとSnowflake側で重複していたメトリクス定義を解消し、一元管理を目指す取り組みである。\n\ndbtのMetricFlowで書いた定義を、Ossieを通じてSnowflakeのSemantic ViewやBIツール（Lightdash）で共有する流れを解説。現状では発展途上の技術であり、AI（Cortex Analyst）との連携を含め、どこまで一元管理が可能かを実証している。","importance":7},{"title":"【分析】「私はMAGAではない」　マスク氏の方向転換が発する強烈なサイン","url":"https://www.cnn.co.jp/usa/35255243.html","source":"Hatena","published_at":"2026-11-21 09:39","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"イーロン・マスク氏が「MAGAではない」と発言、政治的立場の転換か","summary":"米実業家イーロン・マスク氏が、ニューヨークで開催されたフォーラムにて、自身はトランプ氏の「MAGA（米国を再び偉大に）」運動に賛同しておらず、イデオロギー的には穏健であると主張しました。過去に多額の資金を投じてトランプ氏を支援してきた経緯があるだけに、この発言は大きな波紋を呼んでいます。\n\nこの方向転換は、民主党が議会で実権を握る中での自己防衛や、自身の事業に対する調査を回避するための戦略的な動きと見られています。世界的な富豪によるこの姿勢の変化は、トランプ氏を支持してきた他のIT企業幹部や組織に対しても、今後の政治的距離感を見直す重要なサインとなる可能性があります。","importance":7},{"title":"MetaのAIアシスタント搭載小型デバイス「Muse Charm」の価格は4万円台か","url":"https://gigazine.net/news/20261120-muse-charm-may-cost-300-usd/","source":"Hatena","published_at":"2026-11-20 13:45","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"MetaのAI搭載デバイス「Muse Charm」が300ドルで年末発売か","summary":"Metaが発表したキーチェーン型のAIデバイス「Muse Charm」の価格が300ドル（約4万7700円）になる見込みと報じられました。2026年12月のホリデーシーズンに向けた発売が予想されています。\n\n本デバイスはローカル動作するAIエージェント「Muse」を搭載し、ディスプレイやカメラを備えています。テキスト中心の競合端末に対し、アバター表示機能やキャリアのデータプラン付属などが差別化要因となりそうです。","importance":7},{"title":"Codex App の Computer Use はどういう仕組みで動いているのか - Qiita","url":"https://qiita.com/TaigoKuriyama/items/850a26760fc3c8d111ad","source":"Hatena","published_at":"2026-11-20 14:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Codex AppのComputer Use機能：MCPサーバーとSkillによるUI操作の仕組み","summary":"AIが画面を認識してアプリを操作する「Computer Use」が、Codex Appで実用化されています。本記事では、その仕組みをMCPサーバーとSkillの構成から読み解きます。\n\nComputer Useは、モデルが画面状態を見て操作を決定し、実行側がそれを実行するループ構造です。Codex Appでは、操作のガードレールを定義する「Skill」と、UI操作プリミティブを提供する「MCPサーバー」が連携することで、安全かつ効率的なローカルアプリ操作を実現しています。","importance":9},{"title":"SSDの価格は2027年後半に下落し始める可能性あり","url":"https://gigazine.net/news/20261120-ssd-prices-outlook/","source":"Hatena","published_at":"2026-11-20 22:06","genre":"other","genre_label":"総合・その他IT","headline":"SSD価格は2027年後半に下落予測、HDDは高止まりが続く見通し","summary":"アナリストの分析によると、SSDの価格は2027年後半に供給過多となり下落に転じる可能性がある一方、HDDは2028年まで高止まりが続く見通しです。HDD市場はクラウド事業者との長期契約が支配的であるため、価格調整が遅れる傾向にあります。\n\nSSDに関しては、中国メーカーの生産量増加が価格押し下げ要因になると予測されています。ただし、数年前の安値水準に戻ることは期待できず、緩やかな下落にとどまる見込みです。ストレージ購入を検討しているユーザーは、用途に応じて購入時期を見極める必要があります。","importance":5},{"title":"政府システムからファイル流出か、個人情報含む恐れ　デジタル庁発表 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUA20A0V0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 22:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁、政府システムへの不正アクセスでファイル流出の恐れ","summary":"デジタル庁は、政府のネットワークシステム「ガバメントソリューションサービス（GSS）」への不正アクセスにより、会議資料を含むファイルが流出した可能性があると発表しました。個人情報が含まれている恐れがあり、現在調査が進められています。\n\nGSSは25の政府機関が利用するシステムであり、9月にも大規模な個人情報漏洩が発生したばかりです。相次ぐ政府システムのセキュリティインシデントは、国家レベルでのサイバー対策の脆弱性を露呈しており、早急なシステム点検と対策強化が求められています。","importance":9},{"title":"「Visual Studio 2026」に長期サービスチャネル「LTSC 18.11」、2028年11月まで修正を提供／当初予定の1年から2年に延長。v18.12では「Copilot Chat」が新エンジンに","url":"https://forest.watch.impress.co.jp/docs/news/2158151.html","source":"Hatena","published_at":"2026-11-20 17:58","genre":"web","genre_label":"Web開発・言語","headline":"Visual Studio 2026 LTSC版のサポートが2年に延長","summary":"Microsoftは「Visual Studio 2026」の長期サービスチャネル（LTSC）版「LTSC 18.11」のサポート期間を、当初の1年から2年に延長しました。2028年11月までセキュリティ修正が提供されます。\n\nまた、安定版v18.12では「Copilot Chat」の基盤が刷新され、Microsoft Copilot SDKを採用。エージェントスキルの共用やセキュリティレビュー機能などが強化されました。組織の安定運用と最新AI機能の活用という両面での改善が進んでいます。","importance":7},{"title":"モダンな情シスは、AIエージェントを育て、任せ、圧倒的な生産性を生む｜kajinari | モダンな情シス","url":"https://note.com/kajinari/n/n19c73d819b14","source":"Hatena","published_at":"2026-11-21 00:27","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"情シス業務をAIエージェント化、NOTAの生産性向上事例","summary":"NOTAの情シスチームは、Claudeを活用してアカウント発行や権限付与などの定型業務をAIエージェントに自動化させ、圧倒的な生産性を実現しています。3名体制で500名以上の社員を支えるため、API操作を前提とした環境整備を徹底しました。\n\nAIがJiraやSlackの依頼を読み取り、作業から報告までを完結させる仕組みを構築しています。AIが操作できない重要な判断のみを人間が行う「Work with AI」の好例であり、API非対応のSaaSを淘汰する戦略的なIT環境構築が、モダンな情シスのあり方を示しています。","importance":8},{"title":"万博跡地は今どこまで更地になった？ 衛星の SAR 強度と夜間光で追ってみた（Sentinel-1 × VIIRS）","url":"https://zenn.dev/syu_tan/articles/002_expo_site_sar","source":"Zenn","published_at":"2026-11-20 11:45","genre":"other","genre_label":"総合・その他IT","headline":"衛星データSARと夜間光で追う大阪・関西万博跡地の解体状況","summary":"2025年大阪・関西万博閉幕後の会場跡地について、Sentinel-1のSAR（合成開口レーダー）強度画像と夜間光データを用いて、更地化の進捗を可視化した事例。SARは雲や夜間に関係なく地上の構造物を検知できるため、解体状況の追跡に適している。\n\n解析の結果、大屋根リングの解体は2026年1月以降に加速し、区域ごとに解体順序が異なる様子が確認された。光学衛星画像よりもSARの方が構造物の変化を捉えるまでにタイムラグがある点など、衛星データの特性を活かした分析手法が示されている。","importance":5},{"title":"1万円のシンセをAIで魔改造。電子楽器のファームウェア開放が始まった | ギズモード・ジャパン","url":"https://www.gizmodo.jp/article/0b0516f2-94f8-442e-bdae-2987f090be13/","source":"Hatena","published_at":"2026-11-20 23:31","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AIによる電子楽器のファームウェア開放と魔改造ブーム","summary":"安価なガジェットシンセ「FM-1」において、ユーザーによるカスタムファームウェアの開発が活発化しています。AIコーディングツールの普及により、プログラミング経験が少ないユーザーでも機能を拡張できるようになり、楽器の「魔改造」がトレンドとなっています。\n\nメーカー側もこれを排除せず、SDKやソースコードを公開してコミュニティを支援する動きを見せています。ハードウェアと基本OSだけを提供し、機能はユーザーがAIを使って育てていくという新しいビジネスモデルが、楽器業界に革新をもたらそうとしています。","importance":6},{"title":"KaggleのポケモンカードAI対戦コンペ(PTCG AI Battle Challenge)の解法と学び","url":"https://zenn.dev/retrieva_tech/articles/8a1fa7ae2e28ee","source":"Zenn","published_at":"2026-11-20 14:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"KaggleポケモンカードAIコンペで銀メダルを獲得した模倣学習と強化学習の解法","summary":"ポケモンカードのAI対戦コンペにおいて、6層Transformerを用いたエージェントで銀メダルを獲得した事例。計算資源と時間が限られた環境下で、探索を行わずモデルの判断力に特化する戦略を採用しました。\n\n上位エージェントの対戦ログを用いた模倣学習を主軸とし、盤面情報のトークン化や正解ラベルの揺れを解消する前処理が勝率向上に寄与しました。探索を排除し、モデルの判断精度を高めることで、限られた計算時間内での最適解を導き出しています。","importance":8},{"title":"政府の内部資料流出か、基幹システムに不正アクセス　デジタル庁発表：朝日新聞","url":"https://www.asahi.com/sp/articles/ASVCN30WCVCNULFA01NM.html?linkType=article&id=ASVCN30WCVCNULFA01NM","source":"Hatena","published_at":"2026-11-20 19:55","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁の基幹システムで不正アクセス、内部資料流出の可能性","summary":"デジタル庁は、政府の基幹ネットワークシステム「ガバメントソリューションサービス（GSS）」において不正アクセスを検知し、内部資料が流出した可能性があると発表しました。11月12日にサービスを停止し、調査を進めています。\n\n不正アクセスは少なくとも7月30日から11月12日の間に発生していたと見られています。GSSは政府職員が会議資料などを共有するために利用しており、個人情報が含まれている恐れもあります。政府は警察や専門家と連携し、被害の全容解明を急いでいます。","importance":9},{"title":"【HTB】CODEBLUE2026 CTF - Kasio","url":"https://zenn.dev/taksecbe/articles/codeblue2026-htb-ctf","source":"Zenn","published_at":"2026-11-20 00:32","genre":"other","genre_label":"総合・その他IT","headline":"CODEBLUE 2026 CTF「Kasio」のPwn問題Writeup","summary":"CODE BLUE 2026で開催されたCTFのPwn問題「Kasio」の攻略記録。Heap問であり、UAF（Use-After-Free）を利用してlibcリークを行い、House of Huskの手法を応用してprintfのフォーマット指定子を悪用する解法が示されている。\n\n独自のprintfフォーマット指定子を登録する関数を悪用し、関数ポインタをsystem関数に書き換えることでシェルを奪取した。久しぶりのPwn問題への挑戦と、ファーストブラッド獲得までの試行錯誤が詳細に綴られている。","importance":5},{"title":"巨大なAPI Gateway用OpenAPI(Swagger)ファイルをTypeSpecで整理整頓","url":"https://zenn.dev/cariot_dev/articles/70944a671647a8","source":"Zenn","published_at":"2026-11-20 17:44","genre":"web","genre_label":"Web開発・言語","headline":"巨大なOpenAPI定義をTypeSpecで整理・リファクタリング","summary":"15,000行を超える巨大なOpenAPI定義ファイルを、Microsoft製のAPI定義言語「TypeSpec」へ移行した事例が紹介されました。TypeScriptライクな構文による高いメンテナンス性と、ファイル分割の容易さが導入の決め手となりました。\n\n移行にあたっては、現行のOpenAPI 2.0から3.0への変換も同時に実施。TypeSpecのデコレータを活用して、CORSやプロキシ統合などの複雑な仕様を効率的に管理する手法が解説されています。","importance":7},{"title":"情報漏洩3億件超の時代、経営者が問われるのは「どう守るか」よりも「何を持たないか」、顧客情報を預かる資格 KARTEへの不正アクセスとソースネクストの大量流出が示した、顧客情報を持ちすぎる経営の死角 | JBpress (ジェイビープレス)","url":"https://jbpress.ismedia.jp/articles/-/98148","source":"Hatena","published_at":"2026-11-20 20:43","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"情報漏洩時代、経営者に求められる「持たない経営」の視点","summary":"相次ぐ大規模な情報漏洩事案を受け、経営陣の技術リテラシー不足が深刻な問題として指摘されています。現場に責任を押し付けるのではなく、経営層が「自社がどのような情報を、なぜ保有しているのか」を明確に定義し、不要な情報を極力持たない「持たない経営」への転換が求められています。\n\nDXやクラウド化が進む中で、システムは事業の根幹となっています。経営陣がシステムリスクを正しく理解し、適切な予算と裁量を現場に与えることが、インシデントを防ぐための不可欠な条件です。顧客情報を預かることの重みを再認識し、セキュリティを経営課題の最優先事項として捉える必要があります。","importance":8},{"title":"ZOZO、1518万人分の顧客情報流出　委託先に不正アクセス - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUC20APN0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 21:09","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ZOZOは20日、通販サイト「ZOZOTOWN」に登録された1518万人分の顧客情報などが流出したと発表した。","summary":"ZOZOは20日、通販サイト「ZOZOTOWN」に登録された1518万人分の顧客情報などが流出したと発表した。委託先のプレイドが提供するサービス「KARTE（カルテ）」が不正アクセスを受けた。\n\nZOZOTOWNに登録された会員IDや年齢、性別などの個人情報1518万人分が該当する。ファッションアプリ「WEAR by ZOZO」に登録された約1393万人、ZOZOTOWNへの出店企業の担当者の氏名や企業名など約2.4万人の情報が含まれる。\n\n13日に委託先から情報漏洩の可能性があるとの報告を受けた。その後に不正アクセスを受けた委託先システムとのデータ連携を遮断した。\n\n二次被害は現時点で確認されていないとしている。外部サービス上で管理する情報の管理を定期的におこなうなど、個人情報の取り扱いを見直し再発防止に努めるとしている。","importance":5},{"title":"同じ内容でも言語でトークン数は何倍違う？日本語・中国語・韓国語・タイ語を6つのトークナイザーで比べてみた","url":"https://zenn.dev/aiforall/articles/5069b7c19696bf","source":"Zenn","published_at":"2026-11-20 12:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"言語によるトークン数の違いを6つのトークナイザーで徹底比較","summary":"LLMの料金やコンテキストウィンドウに直結する「トークン数」について、英語・日本語・中国語・韓国語・タイ語を6つのトークナイザーで比較検証。日本語は英語の約1.9倍のトークンを消費するケースが多く、言語によるコスト格差が浮き彫りになりました。\n\n語彙に多く含まれる言語ほどトークン効率が良い傾向があり、OpenAIの新世代トークナイザーでは英語以外の言語効率が大幅に改善されています。モデル選定やコスト試算において、トークナイザーの特性を理解することの重要性が示されました。","importance":8},{"title":"【速報】三井住友銀で情報漏えい、最大1400万件","url":"https://www.47news.jp/15262461.html","source":"Hatena","published_at":"2026-11-20 19:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"三井住友銀行で最大1400万件の顧客情報漏えい、委託先が被害","summary":"三井住友銀行は、業務委託先であるプレイドのサービスが不正アクセスを受けた影響で、最大約1400万件の顧客情報が漏えいした可能性があると発表しました。\n\n本件は、委託先のセキュリティインシデントが金融機関の顧客データに波及した事例です。詳細な被害状況や流出した情報の範囲については現在調査中であり、今後の対応が注目されます。","importance":9},{"title":"Go runtime - Bootstrap","url":"https://zenn.dev/aqyuki/articles/go-runtime-bootstrap","source":"Zenn","published_at":"2026-11-20 17:40","genre":"web","genre_label":"Web開発・言語","headline":"Goランタイムの初期化プロセス「Bootstrap」を徹底解説","summary":"Goランタイムの起動からプログラム実行までの流れを解説するシリーズの第2回。OSスレッド（M）やGoroutine（G）、仮想CPU（P）の初期化を含む「Bootstrap」の仕組みが詳細に説明されています。\n\nプログラム起動時のレジスタ退避から、runtime.g0/m0の初期化、スケジューラーの準備、そしてユーザー定義のmain.main実行に至るまでのステップを追うことで、Goの実行基盤に対する深い理解が得られます。","importance":7},{"title":"斜め上からやってきた「SaaSの死」｜ninoya 古越","url":"https://note.com/aatoku/n/n129df4db50ba","source":"Hatena","published_at":"2026-11-20 13:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"データ流出リスクとAI活用で揺らぐSaaSの「ロックイン」ビジネスモデル","summary":"相次ぐ情報流出事件を受け、顧客データを外部SaaSに預けることへの懸念が高まっています。これにより、一度導入すると解約しにくい「ロックイン」を前提とした従来のSaaSビジネスモデルが岐路に立たされています。\n\n今後は、データを自社環境に置いたままAIでシステム構築を支援する「AX」の台頭が予想されます。高い営業コストを長期契約で回収するモデルから、AI活用による低コスト・高セキュリティな構築支援へと、ITビジネスの競争軸が変化しつつあります。","importance":8},{"title":"RTKの走行データ収集でAndroidの記録アプリを外から監視する","url":"https://zenn.dev/nauh_blog/articles/b60cd6973c8a3f","source":"Zenn","published_at":"2026-11-20 18:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"RTK走行データの収集効率化、Androidアプリの遠隔監視システム","summary":"RTK受信機を用いた車両走行データの収集において、記録の停止や精度低下をリアルタイムに検知するAndroid監視アプリの開発事例が紹介されました。ドライバーが運転中に画面を確認できない状況下で、管理画面から状態を把握し、問題を即座に対処する仕組みです。\n\n監視アプリは、受信機のNMEAセンテンスやAndroidのシステム情報を読み取り、HTTPSで管理サーバーへ定期送信します。これにより、走行のやり直しを減らし、効率的なデータ収集を実現しています。","importance":5},{"title":"どれだけGeminiが賢くなってもAIオタクが避ける理由。ついに解消の可能性 - すまほん!!","url":"https://smhn.info/202611-gemini-subscription-third-party-harness-december-2","source":"Hatena","published_at":"2026-11-20 23:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Geminiのサブスクリプションが外部ツールで利用可能になる可能性","summary":"GoogleのGemini担当幹部が、12月2日に「最初の一歩」を踏み出すと示唆しました。これは、Geminiの有料プラン契約者が、サードパーティ製のAIエージェントツール（ハーネス）からGeminiを直接利用できるようになる可能性を示しています。\n\nこれまでGeminiは、Google公式の「Antigravity」環境以外での利用が制限されており、これが開発者やAIオタクがClaudeやChatGPTへ流れる要因となっていました。この制限が緩和されれば、Geminiの利用者が大幅に拡大し、AIエージェント市場での競争が激化することが予想されます。","importance":7},{"title":"[アップデート] AWS STS の GetScopedCredentials で権限と有効期間を絞った認証情報を作ってみた | DevelopersIO","url":"https://dev.classmethod.jp/articles/aws-sts-get-scoped-credentials/","source":"Hatena","published_at":"2026-11-21 04:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS STSの新API「GetScopedCredentials」で権限を動的に絞り込み","summary":"AWS STSに、既存の一時認証情報から権限や有効期間をさらに絞り込んだ認証情報を作成できる「GetScopedCredentials」APIが追加されました。ロールを引き継ぐことなく、IDを維持したまま最小権限での操作が可能になります。\n\n主なユースケースとして、AIエージェントに対して必要な権限のみを付与するシナリオが想定されています。セッションポリシーの適用や有効期間の短縮が容易になり、セキュリティの向上が期待できます。また、認証情報の重ねがけによる多層的な権限制限も可能で、より柔軟なアクセス制御が実現します。","importance":8},{"title":"Spring ProfileでAWSとAWS Emulatorを切り替える","url":"https://zenn.dev/enchanter_one/articles/e8a849e6080f80","source":"Zenn","published_at":"2026-11-20 14:59","genre":"web","genre_label":"Web開発・言語","headline":"Spring Profileを活用したAWSとAWS Emulatorの効率的な切り替え手法","summary":"開発環境において、本物のAWSとAWS Emulatorを環境変数SPRING_PROFILES_ACTIVEで簡単に切り替える手法を解説。AWS Emulatorは統合テストや日常的な動作確認に、本物AWSはCloudFormationによる環境構築時の疎通確認に役割を分担することで、テストケースの削減とシンプルな構成維持を実現します。\n\nSpring BootアプリケーションはDocker Network経由で接続し、JUnitテストはWSLから接続します。AWS SDKのクライアントをBeanとしてDIすることで、コード変更なしに接続先を切り替え可能にしました。本番環境への影響を抑えつつ、ローカル開発の効率を最大化する実践的な構成例です。","importance":7},{"title":"職業訓練でHTMLを学んだ後にSES会社に入社、Javaとphpの開発経験ありと経歴詐称でPythonの現場に送り込まれ、初日にリーダーから「君何ができんの？」と詰められた話","url":"https://togetter.com/li/2772850","source":"Hatena","published_at":"2026-11-20 18:24","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"SESの経歴詐称問題、未経験者が現場で直面する過酷な現実","summary":"職業訓練でHTMLを学んだだけのエンジニアが、SES会社によってJavaやPHPの経験者と経歴詐称され、Pythonの現場に送り込まれたという体験談が話題になっています。現場初日にスキル不足を指摘され、精神的に追い詰められるというSES業界の構造的な闇が浮き彫りになりました。\n\nこの事例は、人手不足を背景としたSES業界の不適切な営業手法や、新人研修の形骸化を象徴しています。エンジニア側には自衛のためのスキルアップが求められる一方、企業側には適切なマッチングと育成体制の構築が急務です。","importance":6},{"title":"初心者がAIとMAXのAPKを解析してみた","url":"https://zenn.dev/aki0804/articles/d4ec272cf5f871","source":"Zenn","published_at":"2026-11-20 10:34","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AIエージェントを活用したAndroidアプリ「MAX」の静的解析","summary":"ロシアのスマホでプリインストールが義務化されたメッセンジャーアプリ「MAX」のAPKを、AIエージェントの補助を得てリバースエンジニアリングした事例。本文送信処理、VPN関連の制限、診断データ送信の仕組みを調査した。\n\n静的解析の結果、本文送信はサーバー側で復元可能な設計である可能性が高いことや、VPN利用時の返信制御の実装を確認。特定の条件下での動作は確認できたものの、VPN利用者全員が拒否されるといった極端な制限は観測されなかった。AIを活用した解析の計画・実行プロセスが詳細に記録されている。","importance":6},{"title":"日本のレシートを自宅PCでOCRする：15構成を実レシート11枚で比べた","url":"https://zenn.dev/chaki/articles/4545be3475fdb4","source":"Zenn","published_at":"2026-11-20 13:33","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"自宅PCで日本のレシートをOCRする15構成の精度比較とYomiTokuの優位性","summary":"自宅のミニPC（AMD内蔵GPU）環境で、日本のレシートをOCRする最適な手法を15構成で比較検証。軽量モデルと高精度モデルを組み合わせた「2段読み」を行うYomiTokuが、商品名・金額の読み取りで最も高い精度を示しました。\n\nVLM型は長いレシートで失敗が目立つ一方、従来型のOCRエンジンは安定した性能を発揮。商用利用を想定したNDLOCR-LiteやPP-OCRv6の有用性についても触れており、セルフホスト環境での経費管理アプリ開発に役立つ知見です。","importance":7},{"title":"「Windows Server 2028」で「WSUS」や「SMB 1.0」、「VBScript」などが削除へ／「Windows PowerShell 5.1」「WDS」は非推奨に、レガシーBIOSでの起動も不可","url":"https://forest.watch.impress.co.jp/docs/news/2158261.html","source":"Hatena","published_at":"2026-11-20 20:11","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windows Server 2028でWSUSやSMB 1.0などレガシー機能が削除へ","summary":"次期サーバーOS「Windows Server 2028」のプレビュー版において、WSUS、SMB 1.0、VBScript、WINSなどのレガシー機能が削除されることが明らかになりました。また、PowerShell 5.1やWDSは非推奨となり、レガシーBIOSでの起動もサポート対象外となります。\n\n今回の変更は、セキュリティ強化とモダンな管理手法への移行を促進するものです。特にWSUSの削除は影響が大きく、代替手段への移行計画が求められます。なお、これらの変更はWindows Server 2028に限定され、旧バージョンでは引き続きサポート期間内であれば利用可能です。","importance":8},{"title":"GitHub - RustWTM/RustWTM: Windows task manager and resource governor written in Rust. Monitor processes, manage resource usage, and keep your PC responsive.","url":"https://github.com/RustWTM/RustWTM","source":"Hatena","published_at":"2026-11-21 08:11","genre":"web","genre_label":"Web開発・言語","headline":"Rust製のWindowsタスクマネージャー兼リソース制御ツール「RustWTM」","summary":"「RustWTM」は、Rustで記述されたWindows向けの高度なタスクマネージャー兼リソースガバナーです。プロセスの監視や診断だけでなく、CPUスロットリングやアプリごとのリソース制限、コア配置の制御など、PCの応答性を維持するための強力な機能を備えています。\n\nインストール後はバックグラウンドサービスとして動作し、設定したポリシーに基づいてリソースを自動管理します。また、Telegramボットとの連携やAIプロバイダーを通じた診断機能も搭載しており、開発者やパワーユーザーがWindows環境を詳細に制御・最適化するためのツールとして注目されます。","importance":5},{"title":"https://alpo.ge/remark.pdf","url":"https://alpo.ge/remark.pdf","source":"Hatena","published_at":"2026-11-21 00:14","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"https://alpo.ge/remark.pdf","summary":"Hatenaで注目されている記事: https://alpo.ge/remark.pdf","importance":5},{"title":"Strix HaloにおけるLemonadeの推論速度・精度評価","url":"https://zenn.dev/anjn/articles/05cbd04f980f56","source":"Zenn","published_at":"2026-11-20 12:46","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Strix Halo環境におけるLemonadeを用いたAIモデルの推論速度・精度評価","summary":"Strix Halo機（128GBメモリ）上で、Lemonadeを用いてQwen系列モデルの推論速度と精度を評価。量子化や生成方式（MTPなど）の違いがパフォーマンスに与える影響を検証しました。\n\nQwen3.8-Flash-NextをHalogen構成で動かすモデルが、速度と精度の両面で最も実用的であると結論。思考中の反復現象に対するHalogenの回答枠確保機能の有効性も確認されており、ローカルLLM運用の最適化に役立つデータです。","importance":7},{"title":"POS端末700台超がマルウェア感染、Windowsの脆弱性悪用でカード情報100万件超が流出","url":"https://news.mynavi.jp/techplus/article/20261120-5367457/","source":"Hatena","published_at":"2026-11-20 18:57","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"POS端末700台超がマルウェア感染、脆弱性悪用でカード情報流出","summary":"20カ国以上に設置されたWindows搭載POS端末700台以上がマルウェアに感染し、100万件以上のカード情報が流出しました。攻撃者は2024年12月に修正済みのWindowsの脆弱性「CVE-2024-49138」を悪用し、SYSTEM権限を取得していました。\n\n被害の多くはブラジルに集中しており、長期間更新プログラムが適用されていなかった端末が標的となりました。企業には、POS端末を含む全機器のセキュリティ更新状況の再確認と、不審なアクセスの監視強化が強く求められています。","importance":8},{"title":"Rails の ActionController::Live × gRPC Server Streaming で、AI の返答をリアルタイム","url":"https://zenn.dev/flyingclouds/articles/2b6fa8c0e86a14","source":"Zenn","published_at":"2026-11-20 11:19","genre":"web","genre_label":"Web開発・言語","headline":"RailsとgRPCストリーミングで実現するAI返答のリアルタイム表示","summary":"RailsとPythonのAIサービスをgRPCで接続し、AIの生成結果をブラウザへリアルタイムにストリーミング表示する構成を紹介。gRPCのServer StreamingとRailsのActionController::Live（SSE）を組み合わせる手法を解説する。\n\nポイントは、gRPCクライアントのfork対策、タブ閉じ時の処理継続、nginxのバッファリング無効化など。WebSocketを使わずともSSEで十分な一方向ストリーミングを実現し、接続と生成のライフサイクルを分離することで堅牢な実装が可能となる。","importance":8},{"title":"MetaのMuseを使ってみた: 内部構造とセキュリティの調査","url":"https://zenn.dev/shoyataguchi/articles/b1bc6a96d4b963","source":"Zenn","published_at":"2026-11-20 00:55","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MetaのAIアプリ「Muse」の内部構造とセキュリティ設計","summary":"Metaが提供するAIアプリ「Muse」のUXと内部構造、セキュリティ設計についての調査報告。メインチャットとサイドチャットによる記憶共有や、ユーザー専用のLinux環境でShellやcronを操作できる点が特徴。\n\n記憶機構は、会話ログから「claim（事実や好み）」を抽出し、GraphRAGのような手法で整理・インデックス化している。セキュリティ面では、システムプロンプトのカスタマイズやサンドボックス環境の活用など、エージェントとしての安全性を高める設計がなされている。","importance":8},{"title":"プレイド、「KARTE」不正アクセスの調査結果を公表、2027年1月中旬の段階的な再開を目指す　契約が終了した企業の情報も漏えいの対象に","url":"https://internet.watch.impress.co.jp/docs/news/2158284.html","source":"Hatena","published_at":"2026-11-20 17:54","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"プレイド「KARTE」不正アクセス調査結果、2027年1月中旬再開へ","summary":"株式会社プレイドは、デジタルマーケティングプラットフォーム「KARTE」への不正アクセスに関する調査結果を公表しました。契約終了企業の情報を含む顧客データや認証情報が漏洩した可能性があるとし、2027年1月中旬の段階的なサービス再開を目指します。\n\n同社は侵入経路の遮断に加え、システム構造の改善を含む堅牢化を実施するとしています。情報漏えいの対象となった企業には詳細データが提供される予定であり、再発防止策の策定が急がれます。","importance":8},{"title":"Rails から Python のサービスを gRPC で呼ぶ：はじめてでも本番で使える構成ガイド","url":"https://zenn.dev/flyingclouds/articles/d11dd921ca756b","source":"Zenn","published_at":"2026-11-20 11:18","genre":"web","genre_label":"Web開発・言語","headline":"RailsからPythonサービスをgRPCで呼び出す本番向け構成ガイド","summary":"RailsからPythonのAIサービスをgRPCで呼び出すための、proto定義からテストまでの実践的な構成ガイド。protoファイルを契約書として扱い、RubyとPython双方のコードを生成・管理する手法を推奨している。\n\ngRPCの型や例外をクライアントクラス内に閉じ込め、呼び出し側には値オブジェクトのみを公開する設計が重要。また、Pumaのfork環境における接続管理や、バックグラウンドジョブでのエラーハンドリングなど、本番運用で必須となる注意点が網羅されている。","importance":8},{"title":"Decision ModelはFAQの回答の確認と問い合わせの振り分けに使えるか","url":"https://zenn.dev/genax_corp/articles/20261109-judge-models-faq-check","source":"Zenn","published_at":"2026-11-20 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"FAQ回答評価と問い合わせ振り分けにおけるDecision Modelの有用性検証","summary":"文章生成を行わず判定結果のみを返す「Decision Model」を、FAQの回答評価や問い合わせ振り分けに活用する検証結果を報告。JevやDecisions APIなどのモデルを生成LLMと比較しました。\n\n回答の欠陥見分けではDecision Modelが生成LLMと同等の性能を示し、応答時間やコスト面で優位性があることを確認。一方で、複雑なカテゴリー推定では生成LLMに分があるなど、用途に応じた使い分けの重要性が示唆されています。","importance":7},{"title":"「PostgreSQL 19」が正式リリース、オープンソースのリレーショナルデータベース（RDB）／稼働を止めずにテーブルを最適化できる「REPACK」などの新機能。2031年11月までサポート","url":"https://forest.watch.impress.co.jp/docs/news/2158045.html","source":"Hatena","published_at":"2026-11-20 17:49","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"PostgreSQL 19正式リリース、稼働中のテーブル最適化機能などを追加","summary":"PostgreSQL 19が正式リリースされました。最大の特徴は、稼働を止めずにテーブルの肥大化を解消できる「REPACK」コマンドの追加です。これにより、大規模ワークロードにおける管理負荷が大幅に軽減されます。\n\nその他、クエリプランナーの安定化、論理レプリケーションの強化、JSON形式でのCOPY出力対応など、開発と運用を簡素化する機能が多数追加されました。サポート期間は2031年11月までとなります。","importance":8},{"title":"検索を速くすると、代わりに何が重くなるのか","url":"https://zenn.dev/loglass/articles/9f1c9da491fefa","source":"Zenn","published_at":"2026-11-20 12:00","genre":"web","genre_label":"Web開発・言語","headline":"PostgreSQLの検索高速化手法とトレードオフの定量的比較","summary":"プロダクト開発における検索高速化の手段として、GINインデックス、生成列、マテリアライズドビュー（MV）の仕組みとコストを解説。検索速度を向上させる一方で、書き込み負荷、容量増加、データ鮮度といったトレードオフが発生する。\n\nGINインデックスは部分一致検索に有効だが容量を消費し、生成列は正規化処理を書き込み時に済ませることで検索を劇的に高速化する。実務では、検索対象の特性や更新頻度に応じてこれらの手法を適切に使い分ける必要がある。","importance":7},{"title":"Claude Code の起動時に依存パッケージの脆弱性を調べるハーネスを、既製品と比べたうえで自作した話","url":"https://zenn.dev/no215/articles/claude-code-security-guardrail","source":"Zenn","published_at":"2026-11-20 09:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Code起動時に依存パッケージの脆弱性を自動検知する仕組み","summary":"Claude Codeのセッション起動時に、リポジトリの依存パッケージの脆弱性を自動的にチェックする仕組みを自作した事例。既製品のCVE Sentinelと比較し、取得頻度の制御や秘密情報検出との統合を優先してPythonスクリプトを開発した。\n\nosv-scannerをバックエンドに利用し、起動時フックを活用して1日1回だけ脆弱性情報を更新する設計。Claude Codeの会話履歴を汚さず、必要な時だけ結果を渡すことで、トークン効率とセキュリティを両立させている。","importance":7},{"title":"NVIDIAグラボにて発生していた「SSD無限酷使」不具合の修正バージョンが配信。“何もしてない”のにSSDに数十GB書き込まれていた問題 - AUTOMATON","url":"https://automaton-media.com/articles/newsjp/20261121-480255/","source":"Hatena","published_at":"2026-11-21 09:45","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"NVIDIA GPUドライバーのSSD書き込み不具合、修正版が配信開始","summary":"NVIDIAのGPU向けドライバー「GeForce Game Ready Driver」の一部バージョンで、PC無操作時にもSSDへ数十GB単位の書き込みが発生する不具合が確認されていました。この問題は、最新のドライバーアップデートによって修正されたことが報告されています。\n\nSSDの寿命を縮める可能性があったこの不具合は、ユーザーの間で大きな懸念となっていました。該当するドライバーを使用していたユーザーは、速やかに最新版へアップデートすることが推奨されます。","importance":6},{"title":"WordPressにプラグインなしでGoogle翻訳を組み込んだメモ【インバウンド向け】","url":"https://zenn.dev/noboo/articles/289c07479497e0","source":"Zenn","published_at":"2026-11-20 13:45","genre":"web","genre_label":"Web開発・言語","headline":"WordPressにプラグインなしでGoogle翻訳を組み込むインバウンド向け実装メモ","summary":"インバウンド需要に対応するため、WordPressにプラグインを使わずGoogle翻訳をfunctions.phpに直書きして実装する方法を解説。DBを汚さず、管理コストを最小限に抑える手法です。\n\nブラウザの言語設定に応じた自動切り替えや、不要なバナー・ポップアップの非表示処理をCSS/JSで制御。プラグイン特有の競合やDB肥大化を防ぎつつ、特定の言語切り替えリンクを簡単に設置できるため、店舗系サイトの多言語対応に最適です。","importance":5},{"title":"CLAUDE.md や SKILL.md のルールを Turtle で書き、ルールの書き間違いや矛盾を lint で検査してみた話","url":"https://zenn.dev/hma2moto/articles/turtle-agent-rules-pros-cons","source":"Zenn","published_at":"2026-11-19 23:13","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeのルール管理にTurtle構文を導入しlintで検査する","summary":"Claude Codeの動作ルール（CLAUDE.mdやSKILL.md）を、MarkdownからTurtle構文へ移行した試み。ルール間の関係性や強さを機械可読な形式で定義することで、矛盾や書き間違いをlintで検査可能にした。\n\nRFC 2119に基づいた強さの定義や、例外・理由の構造化により、エージェントの挙動が安定した。Markdownでは曖昧になりがちなルール定義を、Turtleで厳密に記述することで、複雑なプロジェクトにおけるエージェントの制御精度を向上させている。","importance":7},{"title":"CDKからTerraformへ：所有権移譲による本番インフラ無停止のIaC移行","url":"https://zenn.dev/levtech/articles/14befd8e727f32","source":"Zenn","published_at":"2026-11-20 10:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CDKからTerraformへ：所有権移譲による無停止IaC移行","summary":"AWS CDKで管理されていた本番インフラを、サービスを停止させることなくTerraformへ移行した事例。所有権を移譲する手法を用いることで、安全かつ確実にIaCツールを統一した。\n\n手順は、CDK側で削除ポリシーをRETAINに設定し、Terraform側でimportブロックを使用してリソースを取り込むというもの。この手法により、既存リソースを破壊せずに管理主体を切り替えられる。技術的負債の解消や運用コスト削減を目指すチームにとって、非常に参考になる実践的なノウハウである。","importance":9},{"title":"Dockerfileでイメージを作成後、レイヤーとキャッシュの確認","url":"https://zenn.dev/mutsu_zenn/articles/75498c3f4e693b","source":"Zenn","published_at":"2026-11-20 07:00","genre":"web","genre_label":"Web開発・言語","headline":"Dockerfileのレイヤーとキャッシュの仕組みをコマンドで検証","summary":"Dockerfileの命令がどのようにレイヤーとして構築され、キャッシュが再利用されるかを実際にコマンドを打ちながら検証した備忘録。キャッシュはファイルの中身と直前までのレイヤーが同じかどうかで判定されるため、記述順序がビルド速度に直結する。\n\nライブラリのインストールやアプリコードのコピーなど、変更頻度に応じた記述順序の最適化が重要。また、docker historyやdocker system dfを用いたイメージ容量の確認方法など、コンテナの軽量化とビルド効率化の基本がまとめられている。","importance":6},{"title":"1ターンだけ Sonnet に任せるスキルを作ったら、Opus のままより高くついていた話","url":"https://zenn.dev/no215/articles/claude-code-one-turn-model-skill","source":"Zenn","published_at":"2026-11-19 22:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeでモデルを切り替えるスキルの費用対効果を検証","summary":"Claude Codeで会話の途中に下位モデル（Sonnet等）へ切り替えるスキルを作成し、費用を検証した結果。Haikuへの切り替えは安価になったが、Sonnetへの切り替えはかえって高くつく場合があることが判明した。\n\n原因はプロンプトキャッシュのモデル別管理にある。モデルを切り替えると会話履歴全体が書き直され、キャッシュヒットが失われるため、そのターンのコストが跳ね上がる。安易なモデル切り替えは、出力単価の安さをキャッシュの書き直しコストが上回る可能性がある。","importance":6},{"title":"自宅サーバー上のアプリケーションを Cloudflare Tunnel + Access で安全に公開する","url":"https://zenn.dev/bisque/articles/home-server-cloudflare-tunnel-access","source":"Zenn","published_at":"2026-11-20 16:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cloudflare Tunnel + Accessで自宅サーバーを安全に公開","summary":"自宅サーバーをインターネットに安全に公開するための構成として、Cloudflare TunnelとCloudflare Accessの組み合わせが紹介されました。ルーターのポートを開放せずにサービスを公開し、認証をCloudflare側で一元管理することで、セキュリティリスクを最小化します。\n\nAnsibleによる構成管理や、AIエージェント向けのサービストークン活用など、個人開発における効率的かつセキュアな運用手法が具体的に解説されています。","importance":7}]};
